// Prints the SQL that loads cara-2026-10-27.mjs into kb_items. Safe to run twice.
// Run: node supabase/knowledge/build-sql.mjs > supabase/migrations/20261027_cara_knowledge.sql
import { RECORDS, SOURCE, N002 } from './cara-2026-10-27.mjs'

const q = (s) => "'" + String(s).replace(/'/g, "''") + "'"
const arr = (a) => 'array[' + (a || []).map(q).join(',') + ']::text[]'

const out = [
  "-- Cara's family-facing answers from mo-care.com as published 2026-10-27 (her ask: Cara up to date on all we offer).",
  '-- Generated by supabase/knowledge/build-sql.mjs from supabase/knowledge/cara-2026-10-27.mjs. Safe to run twice.',
  `insert into public.kb_sources (id, name, note, kind) values (${q(SOURCE.id)}, ${q(SOURCE.name)}, 'mo-care.com', 'internal')`,
  '  on conflict (id) do update set name = excluded.name, note = excluded.note;',
  '',
]
for (const r of RECORDS) {
  out.push(
    'insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)',
    `values (${q(r.id)}, ${q(r.question)}, ${q(r.answer)}, ${q(r.key)}, ${q(SOURCE.id)}, ${arr(r.topics)}, ${arr(r.alt)}, array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-10-27', 'mo-care.com live pages (Claude, her ask 10-27)', 'na', 'na', 'ok', 1)`,
    'on conflict (id) do update set question = excluded.question, answer = excluded.answer, answer_key = excluded.answer_key,',
    '  topics = excluded.topics, alt_questions = excluded.alt_questions, status = excluded.status, verified_on = excluded.verified_on,',
    '  verified_by = excluded.verified_by, version = kb_items.version + (kb_items.answer is distinct from excluded.answer)::int, updated_at = now();',
    '')
}
out.push(
  '-- N002 held a stale $14 CDS rate. $16 an hour since 2026-10-16, handled by Caring Companions CDS.',
  `update public.kb_items set answer = ${q(N002.answer)}, status = 'verified', verified_on = '2026-10-27',`,
  "  verified_by = 'CDS pay $16 from 2026-10-16 (caringcds.com)', version = version + 1, updated_at = now()",
  `  where id = 'N002' and answer is distinct from ${q(N002.answer)};`, '')
console.log(out.join('\n'))
